import Config

# For development, we disable any cache and enable
# debugging and code reloading.
#
# The watchers configuration can be used to run external
# watchers to your application. For example, we can use it
# to run a bundled production asset.
config :book_api, BookAPIWeb.Endpoint,
  # When using live_replug, don't set reloadable to true
  reloadable: false,
  debug_errors: true,
  code_reloader: true,
  check_origin: false,
  watchers: []

# ## SSL Support
#
# In order to use HTTPS in development, a self-signed
# certificate can be generated by running the following
# command:
#
#     openssl req -new -x509 -key dev/server.key -out dev/server.crt -days 365
#
# Run `mix help phoenix.server` for more information.
#
# The configuration below is also used to run
# phoenix.server in prod.

# ## Logging
#
# Set up the logger level and format.
#
config :logger, :console,
  format: "$time $metadata[$level] $message\n",
  metadata: [:request_id]

# ## Phoenix LiveDashboard
#
# This section is used to configure Phoenix LiveDashboard.
#
# See https://hexdocs.pm/phoenix_live_dashboard for
# more details.

# ## Phoenix LiveView
#
# Configure LiveView to use JavaScript for all forms.
#
config :phoenix, :live_view,
  # When using live_replug, don't set reloadable to true
  reloadable: false,
  layout: {BookAPIWeb.LayoutView, "app.html"}

# ## Phoenix HTML
#
# Configure Phoenix HTML to use JavaScript for all forms.
#
config :phoenix, :html,
  # When using live_replug, don't set reloadable to true
  reloadable: false,
  layout: {BookAPIWeb.LayoutView, "app.html"}

# Custom `:printf` for Phoenix controllers
config :phoenix, :formatting_printers, [
  Phoenix.Controller.Plug.Printer
]

# Custom `:printf` for Phoenix channels
config :phoenix, :channel_logging, true

# Generate the CSRFF token plug
config :phoenix, :guardian, false

# Enable code reloading for development
config :book_api, :code_reloader, true

# Enable hooks
config :phoenix, :hook_modules, []

# Set the default log level to :debug
config :logger, :level, :debug

# Configure your database
config :book_api, BookAPI.Repo,
  database: "book_api_dev.db",
  show_sensitive_data_on_connection_error: true,
  pool_size: 10

# For development, you'll want to access your Phoenix application
# via http://localhost:4000, so we'll configure the server to
# start by default.
#
config :book_api, BookAPIWeb.Endpoint,
  http: [ip: {127, 0, 0, 1}, port: 4000],
  check_origin: false,
  live_view: [signing_salt: "ZmVnYWM="],
  url: [host: "localhost", port: 4000],
  secret_key_base: "bG9uZyBzdW1tZXIgc2VjcmV0IGtleSB0aGF0IGlzIGJhc2U2NCBlbmNvZGVkIGFuZCBpdHMgbG9uZyBlbm91Z2ggZm9yIGVj dG8gc2VjcmV0IGtleQ=="

# Configure phoenix endpoints in dev
config :phoenix, :server, false

# In dev, we don't use the cache
config :book_api, :cache, false
